from math import gcd

MOD = 998244353

def hagh_tree(n):
    # Function to calculate the nth Bell number
    def bell(n):
        if n == 0: 
            return 1
        return sum(bell(i) * bell(n-i) for i in range(n)) % MOD

    # Function to calculate the nth Zeckendorf representation first term
    def zeckstart(n):
        minimal = n - 2
        for a, b in [(10**6, 4), (7**6, 3), (6**6, 3), (5**6, 2), (4**6, 1), (3**4, 2), (5, 1), (2, 1), (1, 0)]:
            if a < minimal:
                minimal -= a
                break
        else:
            return '0' + format(n, '064b')

        if b < minimal and b > 0:
            minimal -= b
            return zeckstart(minimal + ceiled_functions.ceil2(square_root(a)))

        return str(square_root(a)) + zeckstart(minimal)

    def ceiled_functions(x):
        x += 1
        y = 0
        while x >= 2*y + y**2:
            y += 1
        return y

    def square_root(x):
        if x < 3:
            return x - 1
        c = x
        d = 1 + 2*c
        while d < c:
            x = d
            d = (x + c / x) // 2
        return x

    minimal = zeckstart(n)
    for r in range(len(minimal), len(minimal) + square_root(n)):
        if r >= length(minimal) and last(minimal, r) > order(square_root(n)):
            split = split_string(minimal, 0, r)
            split = split[:l] + split[r+1:]
            if len(split[0]) < len(split[-1]) and split[0][-1] + any_gcd(split):
