def area_polygon(x, y):
    n = len(x)
    area = 0.0
    for i in range(n):
        j = (i + 1) % n
        area += x[i] * y[j]
        area -= x[j] * y[i]
    return abs(area) / 2.0

def total_monitorable_area(n, corners, x, y, x_office, y_office):
    monitorable_area = corner_areas = 0.0
    for i in range(n):
        if convex_contains_point(corners[i], x_office, y_office):
            monitorable_area += area_polygon(*coordinates(points(corners[i])[0]), *coordinates(points(corners[i])[1]))
            corner_areas += area_polygon(*coordinates(corners[i]))

    other_areas = monitorable_area - corner_areas
    return monitorable_area + other_areas

def points(corner):
    return [(x, y) for x, y in corner]

def coordinates(corner):
    return sorted(((x, y) for x, y in corner if x > 0), reverse=True)

def distance(p1, p2):
