    top = bottom = False
    top_region = []
    bot_region = []

    for x2, y2 in warehouse:
        if y2 > y_office:
            top_region += [(x2, y2)]
        elif y2 < y_office:
            bot_region += [(x2, y2)]

    for x, y in sorted(top_region, key=lambda p: -distance(p, (0, y_office))):
        if x + distance(p2, (0, y_office)) > x_office and top:
            break
        top = True
        if x < x_office:
            corner_areas += distance(p2, (0, y_office))  # coordinate point is out front of cone of view
        else:
            corner_areas += distance(p2, (0, y_office))  # coordinate actually within the cone
    else:
        if top and not top and x > 0:
            break

    for x, y in sorted(bot_region, key=lambda p: distance(p, (0, y_office))):
        if x < x_office:
            top = False
        else:
            break
        if y < y_office:
