# Function to find if the vertex set S can be reached from the root
def find(graph, vertex_set):
    if not vertex_set:
        return True

    # Create a boolean state array to track visited vertices
    visited = []

    for vertex in vertex_set:
        stack = [vertex]
        visited.append(False)

        while stack:
            vertex = stack.pop()
            if vertex == vertex_set[-1]:
                break

            # Check around the cell in all four directions
            for nei in graph[vertex]:
                if not visited[nei]:
                    stack.append(nei)
                    visited[nei] = True
            visited[vertex] = True

    return True in visited

