from heapq import heappop, heappush

def dijkstra(graph, start, end):
    pq = [(0, start)]
    visited = {start}
    distances = {start: 0}

    while pq:
        distance, current = heappop(pq)
        if current == end:
            break
        visited.add(current)
        for neighbor, weight in graph[current]:
            if neighbor not in visited:
                new_distance = distance + weight
                if new_distance < distances.get(neighbor, float('inf')):
                    distances[neighbor] = new_distance
                    heappush(pq, (new_distance, neighbor))
    return distances[end] if end in distances else float('inf')

def solve(n, w, edges, queries):
    graph = {i: [] for i in range(1, n * 2 + 1)}

    for start, end, w1, w2 in edges:
        graph[start].append((end, w1))
        graph[end].append((start, w2))

    # Assign new weights to the edges
    for i in range(1, n):
        graph[i].append((i + 1, 1))
        graph[i + 1].append((i, 1))

    # Solve each query
    result = []
    for u, v in queries:
        dest = (u + v) % 2 == 0 or u == v
        # If the destination is even, we need to find paths to and from all equal vertices
        if dest:
            dest_edges = [(u + v) // 2, (u + v) // 2 + 1]
            extended_graph = {i: [] for i in dest_edges}
            for start, end, weight in edges:
                extended_graph[start].append((end + dest + 1, weight // 2))
            for start, end, weight in edges:
                extended_graph[end + dest].append((start + dest + 1, weight // 2))
            extended_dest = (dest // 2 + u, dest // 2 + v)
            extended_graph[dest // 2 + u].append((u, 0))
            extended_graph[dest // 2 + v].append((v, 0))

        result.append(max(min(diijkstra(graph, u, v), diijkstra(graph, extended_dest, dest)), diijkstra(extended_graph, dest, dest)))

    return result

