import sys

def get_input():
    t = int(input().strip())
    for _ in range(t):
        n = int(input().strip())
        days = list(map(int, input().strip().split()))
        yield days

def assign_frequencies(days):
    frequencies = []
    frequency_map = {}
    day_index = {}
    sequence = [0] * 25

    for i, station in enumerate(days):
        frequencies.append(station)
        frequency_map[station] = len(frequencies) - 1
        day_index[i] = frequency_map[station]

        # Assign frequencies to stations in increasing order of their activations
        for j in range(station, -1, -1):
            if j > 0:
                sequence[j] = sequence[j - 1] + 1
        day = 1

        # Ensure only higher frequencies are seen on the same day
        while sequence[station] > 24:
            sequence[sequence[station]] -= 1
            day += 1
            sequence[station] = 0

        list_index = day_index[station]
        while day < len(frequencies):
            if frequencies[list_index] == 0:
                break
            elif frequencies[list_index] != day + 1:
                frequencies[list_index] = day + 1
                day_index[list_index] = frequency_map[frequencies[list_index]] = day
            else:
                list_index = list_index + 1 + sequence[list_index] * (-1)**station
            day += 1
    return frequencies

def print_result(days, frequencies):
    print(" ".join(map(str, frequencies)))

for days in get_input():
    frequencies = assign_frequencies(days)
    print_result(days, frequencies)
