from collections import defaultdict

def count_cyclic_strings(n, s):
    # Define patterns for cyclic shifts
    patterns = []
    for i in range(n):
        for j in range(n):
            temp = [s[k] for k in range(n-j+1)]
            if temp:
                patterns.append("".join(temp))

    # Count occurrences of each pattern
    count = defaultdict(int)
    for pattern in patterns:
        if s in pattern:
            count[pattern] += 1

    # Calculate number of distinct cyclic strings
    return len(count) * (n-1)

