def count_cyclic_strings(n, target):
    substrings = find_cyclic_substrings(target, target)

    def dfs(node, length, path):
        if length == 0:
            results.add(tuple(path))
            return
        for i in range(len(substrings[node])):
            for j in substrings[node][i]:
                new_length = length - substrings[node][i][0]
                new_path = path + [j]
                if new_length > 0:
                    dfs(substrings[node][i][j], new_length, new_path)
                else:
                    dfs(node, length - 1, new_path)

    results = set()
    for i in range(len(target)):
        dfs(i, 0, [i])
    return len(results)

