            cur += decode[idx][n + i]
            if cur in decode_set:
                nframe_num[idx].add(idx)
    for key, frame in nframe_num.items():
        nframes[key] |= set()
        for j in frame:
            for i in range(1, n):
                nex = list(decode[j])
                for k in range(i - 1, -1, -1):
                    nex.remove(nex[k])
                    nex.insert(k, nex[i] + nex[k])
                if tuple(nex) in decode_set:
                    nestart = (n * j) + sum(x == '0' for x in decode[j]) * i
                    nframes[key] |= nframes[nestart]
                    if j not in nframes:
                        nframes[nestart] = set(j)
                    else:
                        nframes[nestart] |= set(j)
    return nframes

