from collections import defaultdict

def find_set(parent, i):
    if parent[i] == i:
        return i
    return find_set(parent, parent[i])

def union_set(parent, rank, i, j):
    pi = find_set(parent, i)
    pj = find_set(parent, j)
    if rank[pi] < rank[pj]:
        parent[pi] = pj
    elif rank[pi] > rank[pj]:
        parent[pj] = pi
    else:
        parent[pj] = pi
        rank[pi] += 1

def find_negative(parent):
    total = 0
    for i in range(len(parent)):
        if parent[i] == i:
            total += 1
    return total

def solution(V, queries, graph):
    parent, rank = [i for i in range(V + 1)], [0 for _ in range(V + 1)]
    for u, v in graph:
        union_set(parent, rank, u, v)
    non_zeros = [0 for _ in range(V + 1)]
    for u in sorted(queries):
        parent[u] = u
        non_zeros[find_set(parent, u)] += 1
    max_profit = 0
    for color, count in sorted(enumerate(non_zeros), key=lambda x: (-rank[x[0]], non_zeros[x[0]]) ):
        profit = count * 2 * color
        if profit > max_profit:
            max_profit = profit
        rank[color] -= count
    return max_profit % (10 ** 9 + 7)

