from operator import mul

# function to compute modular inverse using Fermat's little theorem
def modinv(x, p):
    return pow(x, p - 2, p)

# function to compute k-th power mod p using repeated squaring
def powmod(x, k, p):
    result = 1
    while k > 0:
        if (k % 2) == 1:
            result = result * x % p
        x = x * x % p
        k = k // 2
    return result % p

# function to compute factorial mod p
def factmod(n, p):
    return powmod(comb(n, p), (p - 1) // 2, p) * modinv(p, p) % p

# function to compute n! mod p
def factmodp(n, p):
    return reduce(mul, (factmod(i, p) for i in range(1, n+1)), 1) % p

# function to compute the modular multiplicative inverse of b modulo p
def modinv(b, p):
    return pow(b, p - 2, p)

# function to compute gcd for two large numbers
def gcd_large(a, b):
    if a == 0:
        return b
    return gcd_large(b % a, a)

# function to compute the number of unlabeled Hagh trees
def count_hagh_trees(n):
    # base case
    if n == 0:
        return 1
    if n == 1:
        return 5
    if n == 2:
        return 31
    if n == 3:
        return 195

    # variables
    dp = [5, 5, 195, 195 + 295, 8 + 181 + 38, 12 + 252 + 176 + 141]
    accum_dp = sorted(dp, reverse=True)

    # function to compute the number of Hagh trees of size n using dynamic programming
    def hagh_tree_size(n):
        nonlocal accum_dp, dp

        if n == 0:
            return 1
        if n == 1:
            return 5
        if n + 1 in accum_dp:
            return accum_dp[n + 1]
        if n + 2 in accum_dp:
            return accum_dp[n + 2]
        else:
            for i in range(n - 1):
                if gcd_large(dp[i], n) == 1:
                    return accum_dp[n - 1] * factmod(i + 1, n) % n * accum_dp[n - i - 2] % n
            return gp_decode(accum_dp, interpol, n, n - 2) % n

    return hagh_tree_size(n)

