def dfs(graph, node, goal, direction, index):
    if index == len(direction):
        return len(graph[node]) > 0

    current_direction = direction[index]
    for neighbor in graph[node]:
        if neighbor == goal:
            return True

        if direction[index] == 'same':
            if dfs(graph, neighbor, goal, 'same', index + 1):
                return True

        elif direction[index] == 'opposite':
            if not dfs(graph, neighbor, goal, 'opposite', index + 1):
                return False

    return False

