def find_parity_sum(n):
    # Calculate bitwise parity (sum modulo 2)
    return (1 << n.bit_length() - 1)

def max_bitwise_and_k_trees(K, N, edges, values):
    # Count the number of leaf nodes (nodes with zero value)
    leaf_count = 0
    for value in values:
        if value == 0:
            leaf_count += 1

    # If K exceeds the number of leaf nodes, return 0
    if K > leaf_count:
        return 0

    # If K is equal to the number of leaf nodes, use all leaf nodes for the XOR
    if K == leaf_count:
        result = 1
        for edge in edges:
            result = find_parity_sum(result ^ values[edge[0]]) if edge[0] >= len(result) else find_parity_sum(result ^ values[edge[1]])
        return result

    # If K is less than the number of leaf nodes, use all leaves for XOR
    if K == 1:
        result = 0
        for edge in edges:
            result ^= values[edge[0]].bit_length() - 1 if edge[1] >= len(result) else find_parity_sum(result ^ values[edge[1-leaf_count]])
        return result


