from math import inf

def simulate_game(stations, hours, capacity):
    n = len(stations)
    dp = [[0 for _ in range(capacity + 1)] for _ in range(hours + 1)]

    for t in range(1, hours + 1):
        dp[t][0] = max(a + sum(dp[t-1][c] for c in range(1, capacity)), b)

    for station in range(1, n):
        dp[0][station] = inf

    for t in range(1, hours + 1):
        for c in range(1, capacity + 1):
            dp[t][c] = min(dp[t-1][c-1] + max(a + sum(dp[t-1][c-k] for k in range(1, c)), b),
                          dp[t][c-1])
            for station in range(station, n):
                if dp[t][c] == inf:
                    break
                dp[t+1][c - max(a, dp[t][c])] = max(dp[t+1][c - max(a, dp[t][c])], dp[t][c] - max(a, b))

    return dp[hours][capacity]

