from heapq import heapify, heappop

def solve(n, friendships):
    if n < 2:
        return -1

    heap = []
    for i in range(1, n+1):
        heap.append(set([i]))

    for friend_count in friendships:
        n_friends = min(friend_count, n - i + 1)

        for _ in range(n_friends):
            friend = friend_count - 1
            person = heap[friend].pop()
            heap[n-1].add(person)

        for h in heap:
            if not h & friend:
                heapify(h)

    ans = []

    while heap:
        person = heappop(heap)
        if person:
            ans.append(len(person))

    return ans

